from build import dl

TERMS = [
    ('authselect', 'The Fedora tool that generates <code>system-auth</code> and <code>password-auth</code> in <code>/etc/pam.d</code>. REMOTIX never touches what it generates; the local-login line goes into the files of the login screens instead.'),
    ('AVC', 'An Access Vector Cache message: the line in the journal that says SELinux refused something (<code>avc: denied</code>). Read with <code>journalctl -b -g avc:</code>.'),
    ('Ban', 'Block of an address or a user after wrong passwords: 15 minutes, then 1 hour, then 12 hours.'),
    ('Bench (banco)', 'The set of test machines and the variables that select it (<code>RX_BANCO</code>, <code>RX_TEMPO</code>).'),
    ('Child', 'The per-user process, running as that user, that holds the desktop stage, capture, encoder, input and audio.'),
    ('Compositor', 'The Wayland program that draws the desktop: the labwc of Fedora (0.20.2) for XFCE and LXQt, Mutter for GNOME, and for KDE KWin 6.8 alone (<code>--virtual</code>), with no labwc of ours.'),
    ('Declared fallback', 'A different behaviour taken when the intended one is not available, announced by a line of the log that names the decision (for example <code>DECLARED FALLBACK, D-015</code> for the dconf model) so that it can be told from an accident.'),
    ('Detach, reattach', 'The browser leaves and the desktop stays alive; a later login finds it again.'),
    ('firewalld service', 'The definition <code>remotix</code> (<code>/usr/lib/firewalld/services/remotix.xml</code>, port 7447 TCP and UDP). The package defines it and never opens it; the administrator runs <code>sudo firewall-cmd --permanent --add-service=remotix && sudo firewall-cmd --reload</code>.'),
    ('Fixed second', "The rule that a login's answer is not given before a fixed time after the credentials (one second; 2.5 s for a refusal), so that the time says nothing about the account; a farewell for an admitted client is held until it has passed. <code>RCP.md</code> §4.4-bis."),
    ('Forced close', 'The stop that follows the orderly close of a remote desktop when a local login arrives and the orderly close does not finish: on KDE after 5 s (<code>KDE_PRELOCAL_ORDERLY_MS</code>), stopping <code>graphical-session.target</code>.'),
    ('Found again', 'A desktop with no child whose user returns within the few seconds before the root side ends it ("no orphan desktops"); after an orderly stop there is none. <code>rediscover.c</code>.'),
    ('graphical-session.target', 'The systemd user target to which KWin, ksmserver and plasmashell are <code>PartOf</code>; the forced close of KDE for a local login stops it (F36).'),
    ('HTTP/3', 'HTTP over QUIC; carries the page and WebTransport.'),
    ('KWin alone', 'On KDE, KWin 6.8 started as <code>kwin_wayland --virtual</code> by the user unit <code class="sys">plasma-kwin_wayland.service</code>, whose <code>ExecStart</code> a drop-in of REMOTIX replaces with <code>remotix --kwin-virtual</code>; the size of its output is changed by <code>kwin_output_resize()</code> through <code>kde_output_management_v2</code>.'),
    ('Local excludes remote', 'A user with a local graphical session cannot start a remote one.'),
    ('Local-login hold', "The pause of a local graphical login, made by the PAM hook <code>remotix-local-login</code>, until the user's remote desktop is closed. The line that runs the hook is put into the PAM files of the four login screens (gdm, plasmalogin, lightdm, sddm) by <code>remotix-pam-hook</code>."),
    ('Log Out', "The user's request to end the desktop session; it closes the logind session on every desktop."),
    ('Lost frame, poke', 'A frame that KWin did not deliver: a gap in the numbering of its buffers (<code>capture_watch_sequence()</code>, <code>capture_frame_lost()</code>). The cure is a poke, a request to KWin for a new frame (<code>kwin_poke()</code>), at most every 200 ms and never on a still desktop. Not measured with KWin 6.8.'),
    ('Needrestart drop-in', 'The file <code>/etc/needrestart/conf.d/remotix.conf</code>, which tells needrestart never to restart <code>remotix.service</code> by itself, because a restart closes every remote desktop; the service is only listed for a manual restart. It matters only if needrestart is installed, which Fedora does not do by default.'),
    ('Network side', 'The part of the server that runs as user <code>remotix</code> with no capability and holds the sockets.'),
    ('No orphan desktops', 'The rule that a REMOTIX desktop with no child of ours must not stay: the root side ends it.'),
    ('Opus', 'Audio codec; decoded in the page by a WebAssembly build.'),
    ('PAM', 'Pluggable Authentication Modules; the login password is checked through the service <code>remotix</code>.'),
    ('PipeWire', 'Media server used to capture the screen and the sound of the session.'),
    ('plasmalogin', 'The display manager of the KDE desktop on Fedora 45 (package <code>plasma-login-manager</code>); the other three are gdm (GNOME), lightdm (XFCE) and sddm (LXQt).'),
    ('QUIC', 'Encrypted transport over UDP (library ngtcp2, linked statically).'),
    ('RCP/1', "REMOTIX's own protocol, specified in <code>docs/RCP.md</code>."),
    ('remotix-pam-hook', "The script <code>/usr/libexec/remotix/remotix-pam-hook</code> that puts, keeps and takes away REMOTIX's line in the PAM files of the login screens (<code>apply</code>, <code>check</code>, <code>remove</code>, <code>prepare</code>); run by the package scriptlets, the triggers on the login-screen packages and the start of the service."),
    ('Root side', 'The part of the server that stays root: PAM, session birth, start of the network side; it answers a closed list of requests.'),
    ('Round (giro)', 'A run of the checks on one VM; the word <i>giro</i> is used in the names of scripts (<code>giro-selinux.sh</code>) and in the register.'),
    ('RPM Fusion', "The third-party repository from which Fedora gets the H.264 driver of the video card (<code>mesa-va-drivers-freeworld</code>). REMOTIX requires H.264 encoding on the card, so on Fedora enabling RPM Fusion is the administrator's step (decision D1)."),
    ('Runtime dconf profile', "The file <code>$XDG_RUNTIME_DIR/dconf/profile</code>, which the session writes and dconf reads when the variable <code>DCONF_PROFILE</code> is absent: the base profile's first line, <code>system-db:remotix</code>, <code>user-db:remotix</code>, then the rest of the base profile. Removed, or rewritten with the base profile alone, at the end of the session."),
    ('SELinux', 'Mandatory access control of Fedora, always enforcing. The module <code>remotix</code> of the package (<code>selinux/remotix.te</code>, <code>.fc</code>, <code>.if</code>) gives the root side the domain <code>remotix_t</code>, the network side <code>remotix_net_t</code> (the wall), the PAM hook <code>remotix_hook_t</code>, and the file types <code>remotix_exec_t</code>, <code>remotix_dconf_db_t</code>, <code>remotix_prelocal_t</code>. Decision D3.'),
    ('Sentinel', 'The module (<code>sentinel.c</code>) that asks logind whether a user has a local graphical session; its answer is behind the farewells 0x04 and 0x05. It also asks whether power-off, reboot, suspend and hibernate are forbidden, and accepts "no" or "not available".'),
    ('Session life', 'The answer to "is the desktop alive" with three values, <code>SESSION_LIFE_ALIVE</code>, <code>SESSION_LIFE_DEAD</code> and <code>SESSION_LIFE_UNKNOWN</code> (<code>session_life()</code>): dead only when the bus answered and the compositor\'s name has no owner; unknown when the question could not be asked.'),
    ('Stage', 'What a desktop draws on: the compositor and its virtual monitor, with capture and input attached.'),
    ('System dconf database', '<code>/etc/dconf/db/remotix</code>: the locked settings of the remote GNOME session, compiled with <code>dconf compile</code> by the <code>%post</code> scriptlet of the package (and by the service, if it is missing or different, in <code>/run/remotix/dconf-compile.tmp</code>) from key files that the build generates with <code>remotix --dconf-keyfiles</code> from the table <code>DCONF_KEYS</code> of <code>session.c</code>; removed by <code>%postun</code> with the package.'),
    ('VA-API', 'Video Acceleration API; the way to encode on the card where Vulkan Video is missing.'),
    ('VM bench', "The test bench of the Fedora release: four QEMU virtual machines (gnome, kde, xfce, lxqt) installed from the Fedora 45 live images, plus the build VM, with the server's Radeon passed through to one at a time by <code>vfio-pci</code> (<code>server/vm-radeon.sh</code>, <code>prove/banco-vm/</code>, <code>RX_BANCO=vm</code>, deadlines doubled by <code>RX_TEMPO=2</code>). It has a real login screen and SELinux enforcing, which the checks of the local login need; no containers are used."),
    ('Vulkan Video', "Hardware video encoding through Vulkan, a standard interface independent of the maker; tried first, where the card's driver offers it (on Fedora the Radeon takes it; NVIDIA's proprietary driver offers it too)."),
    ('Walls', 'The ordered list of restrictions put on the network side before it starts (<code>walls.c</code>, applied as root just before the exec): identity, capabilities, mounts, seccomp, Landlock, and the SELinux domain <code>remotix_net_t</code> entered through <code>/proc/thread-self/attr/exec</code>.'),
    ('WebTransport', 'Streams and datagrams over HTTP/3, used by the page to speak RCP/1.'),
    ('wheel', "The administrators' group on Fedora; the polkit rules of REMOTIX name <code>wheel</code>, <code>sudo</code> and <code>admin</code>."),
]
CHAPTER = ("Glossary", [("Terms used in this manual", dl(TERMS, "gloss"))])
